from typing import List

def minDeletionSize(A: List[str]) -> int:
    n = len(A)
    m = len(A[0])
    deletions = 0

    for j in range(m):
        for i in range(1, n):
            if A[i][j] < A[i - 1][j]:
                deletions += 1
                break

    return deletions
